// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am) public {
        vm.assume(_am <= address(c).balance);
        c.Initialized();
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));
        assertTrue(success);
    }
}

